import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.CDU0sSpB.js";const m=JSON.parse(`{"title":"Delivery Route and Implementation Plan","description":"Hearth's six delivery phases, from a minimum complete MVP to a long-running Personal Agent OS.","frontmatter":{"title":"Delivery Route and Implementation Plan","description":"Hearth's six delivery phases, from a minimum complete MVP to a long-running Personal Agent OS.","outline":[2,3]},"headers":[],"relativePath":"en/delivery/index.md","filePath":"en/delivery/index.md","lastUpdated":1794017073000}`),s={name:"en/delivery/index.md"};function n(i,e,l,d,h,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="delivery-route-and-implementation-plan" tabindex="-1">Delivery Route and Implementation Plan <a class="header-anchor" href="#delivery-route-and-implementation-plan" aria-label="Permalink to &quot;Delivery Route and Implementation Plan&quot;">​</a></h1><p class="lead">This route answers only two questions: what to build first, and what comes next; and how each phase moves from usable to reliable.</p><h2 id="overall-goal" tabindex="-1">Overall goal <a class="header-anchor" href="#overall-goal" aria-label="Permalink to &quot;Overall goal&quot;">​</a></h2><p>Hearth turns personal digital work into reliable tasks. The route starts from what the user can complete, not from architecture modules: deliver the smallest complete product first, then expand work coverage, proactivity, memory, and multi-device use.</p><h2 id="current-progress" tabindex="-1">Current progress <a class="header-anchor" href="#current-progress" aria-label="Permalink to &quot;Current progress&quot;">​</a></h2><p>As of 2026-11-07, Phase 1 has been accepted: all 15 cross-industry real tasks ran and 13 passed, meeting the 10/15 hard threshold. Phases 2 through 6 have runnable code and automated test loops, but real accounts, real devices, long-running operation, and failure drills remain unfinished, so they cannot be called complete delivery. See <a href="/hearth-os/en/delivery/status.html">Phase 2–6 delivery status</a> for item-level evidence and the <a href="/hearth-os/en/log/day-04.html">Day04 development log</a> for how it was built.</p><h2 id="six-phases" tabindex="-1">Six phases <a class="header-anchor" href="#six-phases" aria-label="Permalink to &quot;Six phases&quot;">​</a></h2><p>Each phase has four steps. Open a phase name for the detailed plan.</p><table tabindex="0"><thead><tr><th>Phase</th><th>Goal</th><th>Current status</th><th>What the user gets</th></tr></thead><tbody><tr><td><a href="/hearth-os/en/delivery/stage-1.html">Phase 1 · Minimum Complete MVP</a></td><td>Deliver the smallest complete product that passes at least 10 of 15 cross-industry real tasks.</td><td><strong>Accepted:</strong> all 15 tasks ran, 13 passed; T07 and T08 remain open boundaries</td><td>A local task workbench that can be used every day across multiple task families</td></tr><tr><td><a href="/hearth-os/en/delivery/stage-2.html">Phase 2 · Everyday Content Work</a></td><td>Expand from the initial cross-industry tasks to email, calendar, documents, tables, and the web.</td><td><strong>Partial:</strong> local sources, document extraction, and the local outbox loop run; real email/calendar access is not connected</td><td>A personal operator that handles everyday content and writes safely after approval</td></tr><tr><td><a href="/hearth-os/en/delivery/stage-3.html">Phase 3 · Desktop Operation</a></td><td>Let Hearth operate desktop software and cross-application workflows without open interfaces.</td><td><strong>Partial:</strong> same-machine Windows pairing, observation, takeover, and allowlisted low-risk actions run; high-risk and isolation work is open</td><td>An assistant that can operate desktop software, pause, take over, and recover from failure</td></tr><tr><td><a href="/hearth-os/en/delivery/stage-4.html">Phase 4 · Proactive Service and Mobile Entry</a></td><td>Work proactively within limited authority and use the phone for approval and takeover.</td><td><strong>Partial:</strong> triggers, suggestions, inbox, and attention budgets run; the mobile entry is not implemented</td><td>An assistant that speaks at the right time and can be approved or taken over from a phone</td></tr><tr><td><a href="/hearth-os/en/delivery/stage-5.html">Phase 5 · Memory and Capability Evolution</a></td><td>Let the system accumulate context and improve methods, with every change visible, correctable, and reversible.</td><td><strong>Partial:</strong> the memory and method-candidate loops run; real long-term use and production comparison are open</td><td>An assistant that accumulates context and improves methods while staying correctable and reversible</td></tr><tr><td><a href="/hearth-os/en/delivery/stage-6.html">Phase 6 · Multi-device and Long-running Operation</a></td><td>Let the same tasks, memory, and authority run safely across devices over the long term.</td><td><strong>Partial:</strong> sync, leases, revocation, backup, and health checks run; real two-device and long-running acceptance is open</td><td>A multi-device, portable, long-running Personal Agent OS</td></tr></tbody></table><h2 id="how-to-proceed" tabindex="-1">How to proceed <a class="header-anchor" href="#how-to-proceed" aria-label="Permalink to &quot;How to proceed&quot;">​</a></h2><ol><li><strong>Complete before expanding.</strong> Complete at least 10 of the initial 15 tasks before adding sources, operation modes, and devices.</li><li><strong>Read-only before writes, low risk before high risk.</strong> Observe first, draft second, and approve execution last.</li><li><strong>Accept every phase with real tasks.</strong> Finished code or finished pages do not count as completion.</li><li><strong>Safety and recovery start in Phase 1.</strong> Approval, artifacts, failure recovery, and permission boundaries are not postponed.</li></ol><p>Start with <a href="/hearth-os/en/delivery/stage-1.html">Phase 1 · Minimum Complete MVP</a>; implemented scope and open items for Phases 2–6 are recorded in <a href="/hearth-os/en/delivery/status.html">delivery status</a>.</p>',12)])])}const u=t(s,[["render",n]]);export{m as __pageData,u as default};
